          }
        }
        if (s2){
            wfputs(s+s2,out3);
        }
    }
    else  {hent(s,o);
        hent2(o,s);
        hent5(s,o);

        int skip=0;
        char *p = strstr(o, "<text ");
        if (p)  { tf=1, p = strchr(p, '>');  skip= (char*)p+1-(char*)o;
        if(p[-1]=='/' /*|| p[2]==0*/) tf=0;  

        }

        if (strstr(o, "</text>") || strstr(o, "</revision>")|| strstr(o, "</page>"))  tf=0;
        if (tf) {
        removeamp(o,s,skip);
        skipline(s,o);

        }
