bool cat(char const * filename_from1, char const * filename_from2, char const * filename_to) {
  FILE* ifile1 = fopen(filename_from1, "rb");
  FILE* ifile2 = fopen(filename_from2, "rb");
  FILE* ofile = fopen(filename_to, "wb");

  do {
    int c=getc(ifile1);
    if (c==EOF) break;
    putc(c,ofile);
  }
  while (!feof(ifile1));
  do {
    int c=getc(ifile2);
    if (c==EOF) break;
    putc(c,ofile);
  }
  while (!feof(ifile2));
  fclose(ifile1);
  fclose(ifile2);
  fclose(ofile);

  return true;
}

