  void PlanCopy(int kind) {
    const unsigned int h = hits_[kind][conf_ctx_], t = tries_[kind][conf_ctx_];
    const double p = (h + 0.5) / (t + 1.0);
    for (int i = 0; i < 256; ++i) dist_[i] = 0;
    int nv = 0;
    for (int i = 0; i < 256; ++i) if (vocab_[i]) ++nv;
