    for (int i = 0; i < 256; ++i) if (vocab_[i]) dist_[i] = rest;
    dist_[expected_] = p;
    active_ = true; kind_ = kind;
    conf_bucket_ = p < 0.5 ? 0 : p < 0.9 ? 1 : p < 0.99 ? 2 : 3;
